-- WeAreDevs Obfuscator 自動デコンパイラ
-- このスクリプトを同じExecutorで実行すると、難読化解除されたコードがコンソールに表示される

local oldLoadstring = loadstring
local oldLoad = load

-- loadstringをフック
loadstring = function(code, chunkname, ...)
    if type(code) == "string" then
        print("=== Deobfuscated Code ===")
        print(code)
        print("========================")
    end
    return oldLoadstring(code, chunkname, ...)
end

-- loadをフック
load = function(code, chunkname, ...)
    if type(code) == "string" then
        print("=== Deobfuscated Code ===")
        print(code)
        print("========================")
    end
    return oldLoad(code, chunkname, ...)
end

